"use client"

import * as React from "react"
import {
    Accordion,
    AccordionContent,
    AccordionGroup,
    AccordionItem,
    AccordionTrigger,
    Alert,
    AlertDescription,
    AlertTitle,
    Badge,
    Banner,
    BottomActionBar,
    Button,
    Card,
    CardContent,
    CardHeader,
    CardTitle,
    CheckList,
    Container,
    DocNote,
    EmptyState,
    Icon,
    List,
    ListItem,
    MetadataList,
    PageHeader,
    Progress,
    RevealSection,
    SafetyBanner,
    SearchableAccordion,
    SectionList,
    SegmentedControl,
    Separator,
    Sheet,
    SheetBody,
    SheetContent,
    SheetDescription,
    SheetHeader,
    SheetTitle,
    Skeleton,
    StatusScreen,
    Stepper,
    Timeline,
    VStack,
} from "@gunjo/ui"
import {
    IconAlertTriangle,
    IconCircleCheck,
    IconClockPause,
    IconDeviceFloppy,
    IconInfoCircle,
    IconListSearch,
    IconPencil,
    IconPlus,
} from "@tabler/icons-react"

import { FieldSet } from "./FieldSet"
import { MedicalEntryFields, PregnancyEntryFields } from "./EntryFields"
import {
    CONDITION_CATEGORIES,
    CONDITION_ITEMS,
    DURATION_LABEL,
    HELP_ITEMS,
    MEDICATION_LABEL,
    NEXT_STEPS,
    PREGNANCY_STATUS_LABEL,
    QUESTIONS,
    STATUS_LABEL,
    type AnswerMap,
    type Entry,
    type MedicalEntry,
    type PregnancyEntry,
    type Question,
    type QuestionId,
    type YesNo,
} from "./data"

/* ------------------------------------------------------------------ */
/* 初期値・ヘルパー                                                     */
/* ------------------------------------------------------------------ */

const EMPTY_ANSWERS: AnswerMap = {
    q1: { value: null, entries: [] },
    q2: { value: null, entries: [] },
    q3: { value: null, entries: [] },
    q4: { value: null, entries: [] },
    q5: { value: null, entries: [] },
}

let entrySeq = 0
function nextEntryId() {
    entrySeq += 1
    return `e${entrySeq}`
}

function createEntry(question: Question): Entry {
    if (question.kind === "pregnancy") {
        return {
            kind: "pregnancy",
            id: nextEntryId(),
            weeks: "",
            weeksUnknown: false,
            dueDate: "",
            dueDateUnknown: false,
            status: "",
            note: "",
        }
    }
    return {
        kind: "medical",
        id: nextEntryId(),
        name: "",
        nameUnknown: false,
        year: "",
        month: "",
        periodUnknown: false,
        duration: "",
        status: "",
        medication: "",
        medicationName: "",
        note: "",
    }
}

const YES_NO_OPTIONS = [
    { value: "no", label: "いいえ" },
    { value: "yes", label: "はい" },
]

type ErrorItem = { id: string; label: string }

/** 入力欄へフォーカスを移す。群コントロールは中の最初の操作子を狙う。 */
function focusField(id: string) {
    if (typeof document === "undefined") return
    const el = document.getElementById(id)
    if (!el) return
    const focusable =
        el instanceof HTMLInputElement ||
        el instanceof HTMLSelectElement ||
        el instanceof HTMLTextAreaElement ||
        el instanceof HTMLButtonElement
            ? el
            : el.querySelector<HTMLElement>(
                  '[role="radio"], input, select, textarea, button, [tabindex]'
              )
    const target = focusable ?? el
    target.scrollIntoView({ block: "center", behavior: "smooth" })
    if (target instanceof HTMLElement) target.focus({ preventScroll: true })
}

/* ------------------------------------------------------------------ */
/* 検証                                                                */
/* ------------------------------------------------------------------ */

function validateAnswers(
    answers: AnswerMap,
    today: Date
): { errors: Record<string, string>; list: ErrorItem[] } {
    const errors: Record<string, string> = {}
    const list: ErrorItem[] = []
    const push = (id: string, message: string, label: string) => {
        errors[id] = message
        list.push({ id, label })
    }

    const thisYear = today.getFullYear()
    const thisMonth = today.getMonth() + 1

    for (const q of QUESTIONS) {
        const answer = answers[q.id]
        const head = `質問${q.order}`

        if (answer.value === null) {
            push(
                `${q.id}-answer`,
                "「はい」か「いいえ」のどちらかを選んでください。",
                `${head}：まだ答えていません`
            )
            continue
        }
        if (answer.value === "no") continue

        if (answer.entries.length === 0) {
            push(
                `${q.id}-entries`,
                "「はい」を選んだときは、1件以上の内容が必要です。",
                `${head}：「はい」なのに内容が1件もありません`
            )
            continue
        }

        answer.entries.forEach((entry, i) => {
            const p = `${q.id}-${entry.id}`
            const where = `${head} ${i + 1}件目`

            if (entry.kind === "medical") {
                if (!entry.nameUnknown && !entry.name.trim()) {
                    push(
                        `${p}-name`,
                        `${q.labels.name}を書くか、「${q.labels.nameUnknownLabel}」を選んでください。`,
                        `${where}：${q.labels.name}`
                    )
                }
                if (!entry.periodUnknown) {
                    if (!entry.year) {
                        push(
                            `${p}-period`,
                            `年を選ぶか、「${q.labels.periodUnknownLabel}」を選んでください。`,
                            `${where}：時期`
                        )
                    } else if (
                        entry.year === String(thisYear) &&
                        entry.month &&
                        Number(entry.month) > thisMonth
                    ) {
                        push(
                            `${p}-period`,
                            "これから先の月は選べません。過ぎた月を選んでください。",
                            `${where}：時期がこれから先になっています`
                        )
                    }
                }
                if (!entry.duration) {
                    push(`${p}-duration`, "選んでください。", `${where}：${q.labels.duration}`)
                }
                if (!entry.status) {
                    push(`${p}-status`, "選んでください。", `${where}：${q.labels.status}`)
                }
                if (!entry.medication) {
                    push(`${p}-medication`, "選んでください。", `${where}：${q.labels.medication}`)
                } else if (entry.medication === "yes" && !entry.medicationName.trim()) {
                    push(
                        `${p}-medicationName`,
                        "名前が分からなければ「名前は分からない」と書いてください。",
                        `${where}：薬・補助具の名前`
                    )
                }
            } else {
                if (!entry.weeksUnknown) {
                    const weeks = Number(entry.weeks)
                    if (!entry.weeks.trim()) {
                        push(
                            `${p}-weeks`,
                            "週数を書くか、「週数は分からない」を選んでください。",
                            `${where}：妊娠週数`
                        )
                    } else if (!Number.isFinite(weeks) || weeks < 1 || weeks > 45) {
                        push(
                            `${p}-weeks`,
                            "1から45までの数で書いてください。",
                            `${where}：妊娠週数`
                        )
                    }
                }
                if (!entry.dueDateUnknown) {
                    if (!entry.dueDate) {
                        push(
                            `${p}-dueDate`,
                            "予定日を選ぶか、「予定日はまだ分からない」を選んでください。",
                            `${where}：出産予定日`
                        )
                    } else {
                        const due = new Date(entry.dueDate)
                        const floor = new Date(today)
                        floor.setHours(0, 0, 0, 0)
                        if (due < floor) {
                            push(
                                `${p}-dueDate`,
                                "過ぎた日付は選べません。これから先の日付にしてください。",
                                `${where}：出産予定日が過ぎた日付です`
                            )
                        }
                    }
                }
                if (!entry.status) {
                    push(`${p}-status`, "選んでください。", `${where}：いまの状況`)
                }
            }
        })
    }

    return { errors, list }
}

/* ------------------------------------------------------------------ */
/* 自前パーツ：エラーの一覧（@gunjo/ui に該当なし）                       */
/* ------------------------------------------------------------------ */

function ErrorSummary({
    items,
    heading,
    onJump,
}: {
    items: ErrorItem[]
    heading: string
    onJump: (id: string) => void
}) {
    const ref = React.useRef<HTMLDivElement>(null)
    React.useEffect(() => {
        ref.current?.focus()
    }, [items])

    if (items.length === 0) return null

    return (
        <div ref={ref} tabIndex={-1} className="outline-none">
            <Alert variant="destructive" icon={<IconAlertTriangle />}>
                <AlertTitle as="h2">
                    {heading}（{items.length}件）
                </AlertTitle>
                <AlertDescription>
                    直したい項目を選ぶと、その欄に移動します。まだ全部を書き終える必要はありません。
                </AlertDescription>
                <List variant="unordered" spacing="tight" className="mt-2">
                    {items.map((item, i) => (
                        <ListItem key={`${item.id}-${i}`}>
                            <button
                                type="button"
                                onClick={() => onJump(item.id)}
                                className="text-left underline underline-offset-2 hover:no-underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                            >
                                {item.label}
                            </button>
                        </ListItem>
                    ))}
                </List>
            </Alert>
        </div>
    )
}

/* ------------------------------------------------------------------ */
/* 画面                                                                */
/* ------------------------------------------------------------------ */

type Step = "form" | "review" | "done"

export default function HealthDisclosurePage() {
    const [ready, setReady] = React.useState(false)
    const [today, setToday] = React.useState<Date | null>(null)
    const [step, setStep] = React.useState<Step>("form")
    const [answers, setAnswers] = React.useState<AnswerMap>(EMPTY_ANSWERS)
    const [errors, setErrors] = React.useState<Record<string, string>>({})
    const [errorList, setErrorList] = React.useState<ErrorItem[]>([])
    const [reviewErrors, setReviewErrors] = React.useState<ErrorItem[]>([])
    const [conditionListOpen, setConditionListOpen] = React.useState(false)
    const [savedAt, setSavedAt] = React.useState<string | null>(null)
    const [acknowledged, setAcknowledged] = React.useState(false)
    const [attestations, setAttestations] = React.useState<Record<string, boolean>>({
        truth: false,
        noOmission: false,
        understood: false,
    })
    const [submitting, setSubmitting] = React.useState(false)
    const [receipt, setReceipt] = React.useState<{ no: string; at: string } | null>(
        null
    )
    const [pendingFocus, setPendingFocus] = React.useState<string | null>(null)

    // 日付に依存する描画はマウント後だけに閉じる（読み込み中の骨組みを兼ねる）
    React.useEffect(() => {
        const timer = window.setTimeout(() => {
            setToday(new Date())
            setReady(true)
        }, 600)
        return () => window.clearTimeout(timer)
    }, [])

    React.useEffect(() => {
        if (!pendingFocus) return
        const id = window.setTimeout(() => {
            focusField(pendingFocus)
            setPendingFocus(null)
        }, 60)
        return () => window.clearTimeout(id)
    }, [pendingFocus])

    const yearOptions = React.useMemo(() => {
        if (!today) return []
        const y = today.getFullYear()
        return Array.from({ length: 11 }, (_, i) => String(y - i))
    }, [today])

    const answeredCount = QUESTIONS.filter((q) => answers[q.id].value !== null).length
    const yesCount = QUESTIONS.filter((q) => answers[q.id].value === "yes").length
    const detailCount = QUESTIONS.reduce(
        (n, q) => n + (answers[q.id].value === "yes" ? answers[q.id].entries.length : 0),
        0
    )

    /* -------------------------------------------------------------- */

    const setYesNo = (question: Question, value: YesNo) => {
        setAnswers((prev) => {
            const current = prev[question.id]
            if (current.value === value) return prev
            const entries =
                value === "yes"
                    ? current.entries.length > 0
                        ? current.entries
                        : [createEntry(question)]
                    : current.entries
            return { ...prev, [question.id]: { value, entries } }
        })
        setErrors((prev) => {
            const next = { ...prev }
            delete next[`${question.id}-answer`]
            return next
        })
    }

    const addEntry = (question: Question) => {
        const entry = createEntry(question)
        setAnswers((prev) => ({
            ...prev,
            [question.id]: {
                ...prev[question.id],
                entries: [...prev[question.id].entries, entry],
            },
        }))
        setPendingFocus(
            `${question.id}-${entry.id}-${question.kind === "pregnancy" ? "weeks" : "name"}`
        )
    }

    const removeEntry = (question: Question, entryId: string) => {
        setAnswers((prev) => ({
            ...prev,
            [question.id]: {
                ...prev[question.id],
                entries: prev[question.id].entries.filter((e) => e.id !== entryId),
            },
        }))
    }

    const updateEntry = (
        question: Question,
        entryId: string,
        patch: Partial<MedicalEntry> | Partial<PregnancyEntry>
    ) => {
        setAnswers((prev) => ({
            ...prev,
            [question.id]: {
                ...prev[question.id],
                entries: prev[question.id].entries.map((e) =>
                    e.id === entryId ? ({ ...e, ...patch } as Entry) : e
                ),
            },
        }))
    }

    const handleSaveDraft = () => {
        const now = new Date()
        setSavedAt(
            `${now.getHours()}:${String(now.getMinutes()).padStart(2, "0")}`
        )
    }

    const goReview = () => {
        if (!today) return
        const result = validateAnswers(answers, today)
        setErrors(result.errors)
        setErrorList(result.list)
        // エラーの一覧そのものにフォーカスを移す（先頭の欄へ飛ばすと、
        // 何件残っているのかを読み上げる前に画面が動いてしまう）
        if (result.list.length > 0) return
        setStep("review")
        window.scrollTo({ top: 0 })
    }

    const backToQuestion = (id: QuestionId) => {
        setStep("form")
        setPendingFocus(`${id}-answer`)
    }

    const handleSubmit = () => {
        const missing: ErrorItem[] = []
        if (!acknowledged) {
            missing.push({
                id: "final-warning",
                label: "告知が事実と違うときに起きることを、まだ確認していません",
            })
        }
        if (!attestations.truth) {
            missing.push({ id: "attestations", label: "「事実をありのままに告知しました」がまだです" })
        }
        if (!attestations.noOmission) {
            missing.push({ id: "attestations", label: "「省いた事実はありません」がまだです" })
        }
        if (!attestations.understood) {
            missing.push({ id: "attestations", label: "「解除されることがあると理解しました」がまだです" })
        }
        setReviewErrors(missing)
        if (missing.length > 0) return
        setSubmitting(true)
        window.setTimeout(() => {
            const now = new Date()
            setReceipt({
                no: `KJ-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}-04821`,
                at: `${now.getFullYear()}年${now.getMonth() + 1}月${now.getDate()}日 ${now.getHours()}:${String(now.getMinutes()).padStart(2, "0")}`,
            })
            setSubmitting(false)
            setStep("done")
            window.scrollTo({ top: 0 })
        }, 900)
    }

    /* -------------------------------------------------------------- */
    /* 読み込み中                                                      */
    /* -------------------------------------------------------------- */

    if (!ready || !today) {
        return (
            <div className="flex min-h-dvh flex-col bg-background" aria-busy="true">
                <PageHeader title="健康状態の告知" subtitle="読み込んでいます" sticky />
                <Container size="sm" className="flex-1 px-4 py-4">
                    <p className="sr-only" role="status">
                        告知の画面を読み込んでいます。
                    </p>
                    <VStack gap={4}>
                        <Skeleton className="h-10 w-full" />
                        <Skeleton className="h-32 w-full" />
                        {[0, 1, 2].map((i) => (
                            <Skeleton key={i} className="h-40 w-full" />
                        ))}
                    </VStack>
                </Container>
            </div>
        )
    }

    /* -------------------------------------------------------------- */
    /* 送信完了                                                        */
    /* -------------------------------------------------------------- */

    if (step === "done" && receipt) {
        return (
            <div className="flex min-h-dvh flex-col bg-background">
                <PageHeader
                    title="健康状態の告知"
                    subtitle="ステップ3／3　受付完了"
                    sticky={false}
                />
                <Container size="sm" className="flex-1 px-4 pb-10">
                    <VStack gap={6}>
                        <Stepper
                            steps={[
                                { label: "告知の入力", state: "completed" },
                                { label: "内容の確認", state: "completed" },
                                { label: "受付", state: "current" },
                            ]}
                        />
                        <StatusScreen
                            headingLevel={1}
                            icon={
                                <Icon
                                    icon={IconCircleCheck}
                                    size="xl"
                                    label="受付完了"
                                    className="text-success"
                                />
                            }
                            title="告知を受け付けました"
                            description="ありがとうございました。ここで入力は終わりです。この先はこちらで進めますので、いま何かしていただくことはありません。"
                            action={
                                <Button variant="outline" type="button">
                                    告知の控えを保存する
                                </Button>
                            }
                            className="py-6"
                        />

                        {/*
                         * 受付番号は StatusScreen の details に入れられなかった。
                         * details は <pre> の等幅・診断ログ向けの見た目で、受付の控えには合わない。
                         */}
                        <Card>
                            <CardHeader>
                                <CardTitle as="h2" className="text-base">
                                    受付の控え
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <MetadataList
                                    wrap
                                    items={[
                                        { label: "受付番号", value: receipt.no },
                                        { label: "受付日時", value: receipt.at },
                                        {
                                            label: "答えた質問",
                                            value: `5問（うち「はい」${yesCount}問・詳細${detailCount}件）`,
                                        },
                                    ]}
                                />
                            </CardContent>
                        </Card>

                        <Card>
                            <CardHeader>
                                <CardTitle as="h2" className="text-base">
                                    この先の流れ
                                </CardTitle>
                            </CardHeader>
                            <CardContent>
                                <Timeline
                                    items={NEXT_STEPS.map((s) => ({
                                        time: s.time,
                                        title: s.title,
                                        description: s.description,
                                        variant:
                                            s.state === "done"
                                                ? ("success" as const)
                                                : s.state === "current"
                                                  ? ("active" as const)
                                                  : ("muted" as const),
                                    }))}
                                />
                            </CardContent>
                        </Card>

                        <Alert variant="info" icon={<IconInfoCircle />}>
                            <AlertTitle as="h2">追加でうかがうことがあります</AlertTitle>
                            <AlertDescription>
                                書かれた内容だけでは判断がつかないとき、担当者からお電話やメールで確認させていただくことがあります。あとから思い出したことがあれば、マイページの「告知の追加」からいつでも足せます。早く伝えていただくほど、ご自身の不利になりにくくなります。
                            </AlertDescription>
                        </Alert>
                    </VStack>
                </Container>
            </div>
        )
    }

    /* -------------------------------------------------------------- */
    /* 確認                                                            */
    /* -------------------------------------------------------------- */

    if (step === "review") {
        const attestationItems = [
            {
                id: "truth",
                label: "事実をありのままに告知しました",
                description:
                    "覚えている範囲のことは書き、分からないことは「分からない」と書きました。",
                checked: attestations.truth,
            },
            {
                id: "noOmission",
                label: "言いにくいという理由で省いた事実はありません",
                description:
                    "書きにくい通院や病名も、隠さずに書きました。",
                checked: attestations.noOmission,
            },
            {
                id: "understood",
                label:
                    "事実と違う告知だと、契約が解除され、給付金を受け取れないことがあると理解しました",
                description:
                    "いま一度、上の内容に間違いがないか見返しました。",
                checked: attestations.understood,
            },
        ]

        return (
            <div className="flex min-h-dvh flex-col bg-background">
                <PageHeader
                    title="告知した内容の確認"
                    subtitle="ステップ2／3"
                    onBack={() => setStep("form")}
                    backLabel="入力に戻る"
                />
                <Container size="sm" className="flex-1 px-4 py-4">
                    <VStack gap={5}>
                        <Stepper
                            steps={[
                                { label: "告知の入力", state: "completed" },
                                { label: "内容の確認", state: "current" },
                                { label: "受付", state: "upcoming" },
                            ]}
                            onStepClick={(i) => {
                                if (i === 0) setStep("form")
                            }}
                        />

                        <Alert variant="default" icon={<IconInfoCircle />}>
                            <AlertTitle as="h2">出す前に、もう一度ご覧ください</AlertTitle>
                            <AlertDescription>
                                ここが最後に直せるところです。どの質問も「訂正する」から入力に戻れます。急がなくて構いません。閉じても、ここまでの内容は残ります。
                            </AlertDescription>
                        </Alert>

                        <ErrorSummary
                            items={reviewErrors}
                            heading="送信の前に、確認が終わっていない項目があります"
                            onJump={(id) => focusField(id)}
                        />

                        <SectionList
                            label="告知した内容"
                            sections={QUESTIONS.map((q) => {
                                const answer = answers[q.id]
                                return {
                                    key: q.id,
                                    title: `質問${q.order}`,
                                    // sublabel は truncate されるため、375px では
                                    // 質問文が読めなくなる。見出しには入れず本文へ回す。
                                    meta:
                                        answer.value === "yes" ? (
                                            <Badge variant="warning" icon={<IconPencil />}>
                                                はい（{answer.entries.length}件）
                                            </Badge>
                                        ) : (
                                            <Badge variant="outline">いいえ</Badge>
                                        ),
                                    content: (
                                        <div className="px-4 py-3">
                                            <VStack gap={4}>
                                                <div>
                                                    <p className="text-sm font-medium">{q.short}</p>
                                                    <p className="mt-1 text-xs leading-relaxed text-muted-foreground">
                                                        {q.title}
                                                    </p>
                                                </div>
                                                {answer.value === "no" ? (
                                                    <p className="text-sm">
                                                        「いいえ」と答えました。おうかがいする内容はありません。
                                                    </p>
                                                ) : (
                                                    answer.entries.map((entry, i) => (
                                                        <div key={entry.id}>
                                                            <p className="mb-1 text-xs font-medium text-muted-foreground">
                                                                {i + 1}件目
                                                            </p>
                                                            <MetadataList
                                                                wrap
                                                                variant="compact"
                                                                items={summarize(q, entry)}
                                                            />
                                                        </div>
                                                    ))
                                                )}
                                            </VStack>
                                        </div>
                                    ),
                                    footer: (
                                        <Button
                                            type="button"
                                            variant="outline"
                                            size="sm"
                                            onClick={() => backToQuestion(q.id)}
                                        >
                                            <Icon icon={IconPencil} size="sm" decorative />
                                            <span className="ml-1">質問{q.order}を訂正する</span>
