function summarize(q: Question, entry: Entry) {
    if (entry.kind === "pregnancy") {
        return [
            {
                label: "妊娠週数",
                value: entry.weeksUnknown ? "分からない" : `${entry.weeks}週`,
            },
            {
                label: "出産予定日",
                value: entry.dueDateUnknown
                    ? "まだ分からない"
                    : formatIso(entry.dueDate),
            },
            {
                label: "いまの状況",
                value: PREGNANCY_STATUS_LABEL.get(entry.status) ?? "未回答",
            },
            { label: "そのほか", value: entry.note || "記入なし" },
        ]
    }
    return [
        {
            label: q.labels.name,
            value: entry.nameUnknown ? "分からない" : entry.name,
        },
        {
            label: "時期",
            value: entry.periodUnknown
                ? "はっきり分からない"
                : `${entry.year === "before" ? "10年より前" : `${entry.year}年`}${
                      entry.month ? `${entry.month}月` : "（月は不明）"
                  }`,
        },
        {
            label: q.labels.duration,
            value: DURATION_LABEL.get(entry.duration) ?? "未回答",
        },
        { label: q.labels.status, value: STATUS_LABEL.get(entry.status) ?? "未回答" },
        {
            label: q.labels.medication,
            value:
                entry.medication === "yes"
                    ? entry.medicationName || "あり"
                    : (MEDICATION_LABEL.get(entry.medication) ?? "未回答"),
        },
        { label: "そのほか", value: entry.note || "記入なし" },
    ]
}

function formatIso(iso: string) {
    if (!iso) return "未回答"
    const [y, m, d] = iso.split("-")
    return `${y}年${Number(m)}月${Number(d)}日`
}

