const FIELD = formGroupVariants()

/** 「分からない」を選べる補助チェックボックス。告知は空欄より「分からない」のほうが良い。 */
function UnknownToggle({
    id,
    checked,
    onCheckedChange,
    label,
}: {
    id: string
    checked: boolean
    onCheckedChange: (v: boolean) => void
    label: string
}) {
    return (
        <div className="mt-1">
            <Checkbox
                id={id}
                checked={checked}
                onCheckedChange={onCheckedChange}
                label={label}
            />
        </div>
    )
}

function EntryShell({
