export function MedicalEntryFields({
    question,
    entry,
    index,
    idPrefix,
    errors,
    yearOptions,
    onChange,
    onRemove,
}: {
    question: Question
    entry: MedicalEntry
    index: number
    idPrefix: string
    errors: Record<string, string>
    yearOptions: string[]
    onChange: (patch: Partial<MedicalEntry>) => void
    onRemove: () => void
}) {
    const labels = question.labels
    const err = (field: string) => errors[`${idPrefix}-${field}`]

    return (
        <EntryShell
            heading={labels.unit}
            index={index}
            onRemove={onRemove}
            removeLabel="この1件を消す"
        >
            {/* 病名 */}
            <FormField
                className={FIELD}
                error={err("name")}
                required={!entry.nameUnknown}
                id={`${idPrefix}-name`}
            >
                <FormLabel>{labels.name}</FormLabel>
                <FormControl>
                    <Input
                        value={entry.name}
                        placeholder={labels.namePlaceholder}
                        disabled={entry.nameUnknown}
                        onChange={(e) => onChange({ name: e.target.value })}
                    />
                </FormControl>
                <FormDescription>{labels.nameHelp}</FormDescription>
                <FormMessage />
                <UnknownToggle
                    id={`${idPrefix}-name-unknown`}
                    checked={entry.nameUnknown}
                    onCheckedChange={(v) =>
                        onChange({ nameUnknown: v, name: v ? "" : entry.name })
                    }
                    label={labels.nameUnknownLabel}
                />
            </FormField>

            {/* 時期（年 + 月） */}
            <FieldSet
                id={`${idPrefix}-period`}
                legend={labels.period}
                description={labels.periodHelp}
                error={err("period")}
                required={!entry.periodUnknown}
            >
                {(aria) => (
                    <VStack gap={2}>
                        <HStack gap={2} align="start">
                            <div className="min-w-0 flex-1">
                                <Select
                                    {...aria}
                                    label="年"
                                    value={entry.year}
                                    disabled={entry.periodUnknown}
                                    onChange={(e) => onChange({ year: e.target.value })}
                                >
                                    <option value="">選んでください</option>
                                    {yearOptions.map((y) => (
                                        <option key={y} value={y}>
                                            {y}年
                                        </option>
                                    ))}
                                    <option value="before">それより前</option>
                                </Select>
                            </div>
                            <div className="min-w-0 flex-1">
                                <Select
                                    id={`${idPrefix}-month`}
                                    label="月"
                                    value={entry.month}
                                    disabled={entry.periodUnknown}
                                    onChange={(e) => onChange({ month: e.target.value })}
                                >
                                    <option value="">分からない</option>
                                    {Array.from({ length: 12 }, (_, i) => String(i + 1)).map(
                                        (m) => (
                                            <option key={m} value={m}>
                                                {m}月
                                            </option>
                                        )
                                    )}
                                </Select>
                            </div>
                        </HStack>
                        <UnknownToggle
                            id={`${idPrefix}-period-unknown`}
                            checked={entry.periodUnknown}
                            onCheckedChange={(v) =>
                                onChange({
                                    periodUnknown: v,
                                    year: v ? "" : entry.year,
                                    month: v ? "" : entry.month,
                                })
                            }
                            label={labels.periodUnknownLabel}
                        />
                    </VStack>
                )}
            </FieldSet>

            {/* 治療期間 */}
            <FormField
                className={FIELD}
                error={err("duration")}
                required
                id={`${idPrefix}-duration`}
            >
                <FormLabel>{labels.duration}</FormLabel>
                <FormControl>
                    <Select
                        value={entry.duration}
                        onChange={(e) => onChange({ duration: e.target.value })}
                    >
                        <option value="">選んでください</option>
                        {DURATION_OPTIONS.map((o) => (
                            <option key={o.value} value={o.value}>
                                {o.label}
                            </option>
                        ))}
                    </Select>
                </FormControl>
                <FormMessage />
            </FormField>

            {/* いまの状態 */}
            <FieldSet
                id={`${idPrefix}-status`}
                legend={labels.status}
                error={err("status")}
                required
            >
                {(aria) => (
                    <RadioGroup
                        {...aria}
                        value={entry.status}
                        onValueChange={(v) => onChange({ status: v })}
                        className="gap-2"
                    >
                        {STATUS_OPTIONS.map((o) => (
                            <RadioGroupItem key={o.value} value={o.value} label={o.label} />
                        ))}
                    </RadioGroup>
                )}
            </FieldSet>

            {/* 薬 */}
            <FieldSet
                id={`${idPrefix}-medication`}
                legend={labels.medication}
                error={err("medication")}
                required
            >
                {(aria) => (
                    <VStack gap={3}>
                        <SegmentedControl
                            {...aria}
                            size="lg"
                            options={MEDICATION_OPTIONS}
                            value={entry.medication || undefined}
                            onValueChange={(v) => onChange({ medication: v })}
                        />
                        <RevealSection
                            open={entry.medication === "yes"}
                            label={`${labels.medication}の内容`}
                        >
                            <FormField
                                className={FIELD}
                                error={err("medicationName")}
                                required
                                id={`${idPrefix}-medicationName`}
                            >
                                <FormLabel>薬・補助具の名前</FormLabel>
                                <FormControl>
                                    <Textarea
                                        rows={2}
                                        value={entry.medicationName}
                                        placeholder="例：血圧を下げる薬を1日1回"
                                        onChange={(e) =>
                                            onChange({ medicationName: e.target.value })
                                        }
                                    />
                                </FormControl>
                                <FormDescription>
                                    名前が分からなければ「名前は分からない」と書いてください。
                                </FormDescription>
                                <FormMessage />
                            </FormField>
                        </RevealSection>
                    </VStack>
                )}
            </FieldSet>

            {/* 補足 */}
            <FormField className={FIELD} id={`${idPrefix}-note`}>
                <FormLabel>そのほか、伝えておきたいこと（任意）</FormLabel>
                <FormControl>
                    <Textarea
                        rows={3}
                        value={entry.note}
                        placeholder="例：手術のあとは通院していません。"
                        onChange={(e) => onChange({ note: e.target.value })}
                    />
                </FormControl>
                <FormDescription>
                    はっきりしないことは、はっきりしないまま書いていただいて構いません。
                </FormDescription>
            </FormField>
        </EntryShell>
    )
}

