export function PregnancyEntryFields({
    entry,
    index,
    idPrefix,
    errors,
    today,
    onChange,
    onRemove,
}: {
    entry: PregnancyEntry
    index: number
    idPrefix: string
    errors: Record<string, string>
    today: Date
    onChange: (patch: Partial<PregnancyEntry>) => void
    onRemove: () => void
}) {
    const err = (field: string) => errors[`${idPrefix}-${field}`]

    const dueLimit = React.useMemo(() => {
        const d = new Date(today)
        d.setMonth(d.getMonth() + 10)
        return d
    }, [today])

    return (
        <EntryShell
            heading="妊娠について"
            index={index}
            onRemove={onRemove}
            removeLabel="この1件を消す"
        >
            <FormField
                className={FIELD}
                error={err("weeks")}
                required={!entry.weeksUnknown}
                id={`${idPrefix}-weeks`}
            >
                <FormLabel>いまの妊娠週数</FormLabel>
                <FormControl>
                    <Input
                        type="number"
                        inputMode="numeric"
                        min={1}
                        max={45}
                        value={entry.weeks}
                        placeholder="例：18"
                        disabled={entry.weeksUnknown}
                        onChange={(e) => onChange({ weeks: e.target.value })}
                    />
                </FormControl>
                <FormDescription>およその週数で構いません。</FormDescription>
                <FormMessage />
                <UnknownToggle
                    id={`${idPrefix}-weeks-unknown`}
                    checked={entry.weeksUnknown}
                    onCheckedChange={(v) =>
                        onChange({ weeksUnknown: v, weeks: v ? "" : entry.weeks })
                    }
                    label="週数は分からない"
                />
            </FormField>

            <FormField
                className={FIELD}
                error={err("dueDate")}
                required={!entry.dueDateUnknown}
                id={`${idPrefix}-dueDate`}
            >
                <FormLabel>出産予定日</FormLabel>
                <FormControl>
                    <DatePicker
                        value={entry.dueDate ? new Date(entry.dueDate) : undefined}
                        disabled={entry.dueDateUnknown}
                        placeholder="年/月/日"
                        startMonth={today}
                        endMonth={dueLimit}
                        disabledDates={[{ before: today }, { after: dueLimit }]}
                        onValueChange={(d) =>
                            onChange({ dueDate: d ? toIsoDate(d) : "" })
                        }
                    />
                </FormControl>
                <FormDescription>
                    これから先の日付だけ選べます。まだ聞いていない場合は下の「分からない」を選んでください。
                </FormDescription>
                <FormMessage />
                <UnknownToggle
                    id={`${idPrefix}-dueDate-unknown`}
                    checked={entry.dueDateUnknown}
                    onCheckedChange={(v) =>
                        onChange({ dueDateUnknown: v, dueDate: v ? "" : entry.dueDate })
                    }
                    label="予定日はまだ分からない"
                />
            </FormField>

            <FieldSet
                id={`${idPrefix}-status`}
                legend="いまの状況について、医師から言われていること"
                error={err("status")}
                required
            >
                {(aria) => (
                    <RadioGroup
                        {...aria}
                        value={entry.status}
                        onValueChange={(v) => onChange({ status: v })}
                        className="gap-2"
                    >
                        {PREGNANCY_STATUS_OPTIONS.map((o) => (
                            <RadioGroupItem key={o.value} value={o.value} label={o.label} />
                        ))}
                    </RadioGroup>
                )}
            </FieldSet>

            <FormField className={FIELD} id={`${idPrefix}-note`}>
                <FormLabel>そのほか、伝えておきたいこと（任意）</FormLabel>
                <FormControl>
                    <Textarea
                        rows={3}
                        value={entry.note}
                        placeholder="例：切迫早産で1週間入院しました。"
                        onChange={(e) => onChange({ note: e.target.value })}
                    />
                </FormControl>
            </FormField>
        </EntryShell>
    )
}

export function toIsoDate(d: Date): string {
    const y = d.getFullYear()
    const m = String(d.getMonth() + 1).padStart(2, "0")
    const day = String(d.getDate()).padStart(2, "0")
    return `${y}-${m}-${day}`
}

"use client"

import * as React from "react"

/**
 * 自前の fieldset / legend ラッパー。
 *
 * @gunjo/ui の Form 系（FormField / FormLabel / FormControl / FormMessage）は
 * 単一のコントロールを label の htmlFor で結びつける作りで、
 * ラジオ群や「年 + 月」のような複数コントロールを1つの問いとしてまとめる
 * 入れ物（fieldset + legend）が無い。RadioGroup / SegmentedControl はどちらも
 * role="radiogroup" の div なので htmlFor では名前が付かず、ここだけ自前で組んだ。
 */
export interface FieldSetProps {
    /** 問いの見出し。legend として読み上げられる */
    legend: React.ReactNode
    /** 補足。aria-describedby で群に結びつける */
    description?: React.ReactNode
    /** エラー文。role="alert" で出し、群を aria-invalid にする */
    error?: React.ReactNode
    required?: boolean
    /** 中の群コントロールに渡す id（フォーカス移動の対象） */
    id: string
    className?: string
    /**
     * 中身。aria 属性を受け取って群コントロールに広げる。
     */
    children: (aria: {
        id: string
        "aria-describedby"?: string
        "aria-invalid"?: boolean
        "aria-required"?: boolean
    }) => React.ReactNode
}

export function FieldSet({
    legend,
    description,
    error,
    required,
    id,
    className,
    children,
}: FieldSetProps) {
    const descriptionId = description ? `${id}-description` : undefined
    const messageId = error ? `${id}-message` : undefined
    const describedBy = [descriptionId, messageId].filter(Boolean).join(" ")

    return (
        <fieldset className={className ?? "flex flex-col gap-1.5"}>
            <legend
                className={`mb-1.5 text-sm font-medium leading-none ${
                    error ? "text-destructive" : "text-foreground"
                }`}
            >
                {legend}
                {required ? (
                    <span aria-hidden="true" className="ml-0.5 text-destructive">
                        *
                    </span>
                ) : null}
            </legend>
            {description ? (
                <p id={descriptionId} className="text-xs font-normal text-muted-foreground">
                    {description}
                </p>
            ) : null}
            {children({
                id,
                "aria-describedby": describedBy || undefined,
                "aria-invalid": error ? true : undefined,
                "aria-required": required || undefined,
            })}
            {error ? (
                <p id={messageId} role="alert" className="text-xs font-medium text-destructive">
                    {error}
                </p>
            ) : null}
        </fieldset>
    )
}
